export interface KnownWebsiteIcon {
  hostnames: readonly string[];
  includeSubdomains?: boolean;
  siteName: string;
  iconDataUrl: string;
}

function imageDataUrl(mimeType: string, base64: string) {
  return `data:${mimeType};base64,${base64}`;
}

const xIcon = imageDataUrl("image/png", "");
const linkedinIcon = imageDataUrl("image/x-icon", "");
const githubIcon = imageDataUrl("image/x-icon", "");
const youtubeIcon = imageDataUrl("image/x-icon", "");
const googleIcon = imageDataUrl("image/x-icon", "");
const googleDocsIcon = imageDataUrl("image/x-icon", "");
const notionIcon = imageDataUrl("image/x-icon", "");
const linearIcon = imageDataUrl("image/x-icon", "");
const openaiIcon = imageDataUrl("image/png", "");
const chatgptIcon = imageDataUrl("image/svg+xml", "");
const anthropicIcon = imageDataUrl("image/x-icon", "");
const claudeIcon = imageDataUrl("image/x-icon", "");
const figmaIcon = imageDataUrl("image/png", "");
const slackIcon = imageDataUrl("image/x-icon", "");
const stackoverflowIcon = imageDataUrl("image/x-icon", "");
const vercelIcon = imageDataUrl("image/x-icon", "");
const cloudflareIcon = imageDataUrl("image/png", "");
const arxivIcon = imageDataUrl("image/png", "");
const feishuIcon = imageDataUrl("image/svg+xml", "");
const rudderIcon = imageDataUrl("image/x-icon", "");

export const KNOWN_WEBSITE_ICONS: readonly KnownWebsiteIcon[] = [
  { hostnames: ["x.com","twitter.com"], includeSubdomains: true, siteName: "X", iconDataUrl: xIcon },
  { hostnames: ["linkedin.com","www.linkedin.com"], siteName: "LinkedIn", iconDataUrl: linkedinIcon },
  { hostnames: ["github.com","www.github.com","gist.github.com"], siteName: "GitHub", iconDataUrl: githubIcon },
  { hostnames: ["youtube.com","www.youtube.com","youtu.be"], siteName: "YouTube", iconDataUrl: youtubeIcon },
  { hostnames: ["google.com","www.google.com"], siteName: "Google", iconDataUrl: googleIcon },
  { hostnames: ["docs.google.com"], siteName: "Google Docs", iconDataUrl: googleDocsIcon },
  { hostnames: ["notion.so","www.notion.so"], siteName: "Notion", iconDataUrl: notionIcon },
  { hostnames: ["linear.app","linear.com"], siteName: "Linear", iconDataUrl: linearIcon },
  { hostnames: ["openai.com","www.openai.com","platform.openai.com"], siteName: "OpenAI", iconDataUrl: openaiIcon },
  { hostnames: ["chatgpt.com","www.chatgpt.com","chat.openai.com"], siteName: "ChatGPT", iconDataUrl: chatgptIcon },
  { hostnames: ["anthropic.com","www.anthropic.com","console.anthropic.com"], siteName: "Anthropic", iconDataUrl: anthropicIcon },
  { hostnames: ["claude.ai"], siteName: "Claude", iconDataUrl: claudeIcon },
  { hostnames: ["figma.com","www.figma.com"], siteName: "Figma", iconDataUrl: figmaIcon },
  { hostnames: ["slack.com","www.slack.com"], siteName: "Slack", iconDataUrl: slackIcon },
  { hostnames: ["stackoverflow.com","www.stackoverflow.com"], siteName: "Stack Overflow", iconDataUrl: stackoverflowIcon },
  { hostnames: ["vercel.com","www.vercel.com"], siteName: "Vercel", iconDataUrl: vercelIcon },
  { hostnames: ["cloudflare.com","www.cloudflare.com"], siteName: "Cloudflare", iconDataUrl: cloudflareIcon },
  { hostnames: ["arxiv.org","www.arxiv.org"], siteName: "arXiv", iconDataUrl: arxivIcon },
  { hostnames: ["feishu.cn","www.feishu.cn","feishuapp.cn","www.feishuapp.cn"], includeSubdomains: true, siteName: "Feishu", iconDataUrl: feishuIcon },
  { hostnames: ["rudderhq.dev","rudder.zeeland.studio"], includeSubdomains: true, siteName: "Rudder", iconDataUrl: rudderIcon },
] as const;

const knownWebsiteIconByHostname = new Map(
  KNOWN_WEBSITE_ICONS.flatMap((icon) => icon.hostnames.map((hostname) => [hostname, icon])),
);

export function resolveKnownWebsiteIcon(input: string | URL): KnownWebsiteIcon | null {
  let url: URL;
  try {
    url = input instanceof URL ? input : new URL(input);
  } catch {
    return null;
  }
  const hostname = url.hostname.replace(/^\[|\]$/gu, "").toLowerCase();
  if (!hostname) return null;
  const direct = knownWebsiteIconByHostname.get(hostname);
  if (direct) return direct;
  for (const [knownHostname, icon] of knownWebsiteIconByHostname.entries()) {
    if (icon.includeSubdomains && hostname.endsWith(`.${knownHostname}`)) return icon;
  }
  return null;
}
